draw:
var pad = 40, x0 = pad, x1 = W - 14, yb = H - 26, yt = 16;
var xmaxDeg = 90, ymax = 1.6;
function X(d) { return x0 + (d / xmaxDeg) * (x1 - x0); }
function Y(v) { return yb - (v / ymax) * (yb - yt); }
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// axes
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(x0, yt); ctx.lineTo(x0, yb); ctx.lineTo(x1, yb); ctx.stroke();
ctx.fillStyle = C.faint;
for (var d = 0; d <= 90; d += 30) {
  ctx.beginPath(); ctx.moveTo(X(d), yb); ctx.lineTo(X(d), yb + 4); ctx.stroke();
  ctx.fillText(d + "°", X(d) - 8, yb + 17);
}
for (var v = 0.5; v <= 1.5001; v += 0.5) {
  ctx.beginPath(); ctx.moveTo(x0 - 4, Y(v)); ctx.lineTo(x0, Y(v)); ctx.stroke();
  ctx.fillText(v.toFixed(1), 8, Y(v) + 4);
}

function curve(f, color, dash) {
  ctx.strokeStyle = color; ctx.lineWidth = 1.8;
  ctx.setLineDash(dash);
  ctx.beginPath();
  for (var i = 0; i <= 120; i++) {
    var dd = xmaxDeg * i / 120, r = dd * Math.PI / 180;
    var xx = X(dd), yy = Y(f(r));
    if (i === 0) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
  }
  ctx.stroke();
  ctx.setLineDash([]);
}

curve(function (r) { return r; }, C.faint, [4, 4]);
curve(function (r) { return r - r * r * r / 6; }, C.figure, [2, 3]);
curve(function (r) { return Math.sin(r); }, C.ink, []);

// labels on curves
ctx.fillStyle = C.faint; ctx.fillText("y = θ", X(62), Y(1.20));
ctx.fillStyle = C.figure; ctx.fillText("θ − θ³/6", X(64), Y(0.72));
ctx.fillStyle = C.ink; ctx.fillText("sin θ", X(70), Y(1.02));

// marker at the chosen angle, with a breathing highlight of the gap
var deg = p.theta, rad = deg * Math.PI / 180;
var s = Math.sin(rad);
var xm = X(deg);
ctx.strokeStyle = C.rule; ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(xm, yt); ctx.lineTo(xm, yb); ctx.stroke();
ctx.setLineDash([]);

var pulse = 1.5 + 1.5 * (0.5 + 0.5 * Math.sin(2 * t));
ctx.strokeStyle = C.accent; ctx.lineWidth = pulse;
ctx.beginPath(); ctx.moveTo(xm, Y(s)); ctx.lineTo(xm, Y(rad)); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(xm, Y(s), 3.5, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(xm, Y(rad), 3.5, 0, 6.2832); ctx.fill();

var err = (rad - s) / s * 100;
out.note = "θ = " + deg.toFixed(0) + "° = " + rad.toFixed(4) +
  " rad,  sin θ = " + s.toFixed(4) +
  ",  error of θ ≈ sin θ: " + err.toFixed(2) + "%";

var pad = 44, x0 = pad, x1 = W - 14, yb = H - 26, yt = 16;
var xlim = 0.5;
var n = p.n;
function X(v) { return x0 + ((v + xlim) / (2 * xlim)) * (x1 - x0); }
var lo = Math.min(Math.pow(1 - xlim, n), Math.pow(1 + xlim, n), 1 - n * xlim, 1 + n * xlim);
var hi = Math.max(Math.pow(1 - xlim, n), Math.pow(1 + xlim, n), 1 - n * xlim, 1 + n * xlim);
var span = Math.max(hi - lo, 0.4), mid = (hi + lo) / 2;
var vlo = mid - span * 0.62, vhi = mid + span * 0.62;
function Y(v) { return yb - ((v - vlo) / (vhi - vlo)) * (yb - yt); }
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, yt); ctx.lineTo(x0, yb); ctx.lineTo(x1, yb); ctx.stroke();
ctx.fillStyle = C.faint;
for (var d = -0.5; d <= 0.5001; d += 0.25) {
  ctx.beginPath(); ctx.moveTo(X(d), yb); ctx.lineTo(X(d), yb + 4); ctx.stroke();
  ctx.fillText(d.toFixed(2), X(d) - 12, yb + 17);
}
ctx.fillText("x", (x0 + x1) / 2 - 3, yb + 17 + 0);
ctx.fillText(vhi.toFixed(2), 6, Y(vhi) + 10);
ctx.fillText(vlo.toFixed(2), 6, Y(vlo) - 2);

// true curve
ctx.strokeStyle = C.ink; ctx.lineWidth = 1.8;
ctx.beginPath();
for (var i = 0; i <= 120; i++) {
  var xx = -xlim + 2 * xlim * i / 120;
  var yy = Math.pow(1 + xx, n);
  if (i === 0) ctx.moveTo(X(xx), Y(yy)); else ctx.lineTo(X(xx), Y(yy));
}
ctx.stroke();

// tangent line
ctx.strokeStyle = C.accent; ctx.lineWidth = 1.8; ctx.setLineDash([5, 4]);
ctx.beginPath();
ctx.moveTo(X(-xlim), Y(1 - n * xlim));
ctx.lineTo(X(xlim), Y(1 + n * xlim));
ctx.stroke(); ctx.setLineDash([]);

ctx.fillStyle = C.ink; ctx.fillText("(1+x)ⁿ", X(0.22), Y(Math.pow(1.22, n)) - 8);
ctx.fillStyle = C.accent; ctx.fillText("1 + nx", X(-0.46), Y(1 - n * 0.46) + 16);

// the reader's point, with a pulsing error bar
var xs = p.x;
var exact = Math.pow(1 + xs, n), approx = 1 + n * xs;
ctx.strokeStyle = C.rule; ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(xs), yt); ctx.lineTo(X(xs), yb); ctx.stroke();
ctx.setLineDash([]);
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5 + 1.5 * (0.5 + 0.5 * Math.sin(2 * t));
ctx.beginPath(); ctx.moveTo(X(xs), Y(exact)); ctx.lineTo(X(xs), Y(approx)); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(X(xs), Y(exact), 3.5, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(xs), Y(approx), 3.5, 0, 6.2832); ctx.fill();

var err = exact === 0 ? 0 : (approx - exact) / exact * 100;
out.note = "n = " + n.toFixed(2) + ", x = " + xs.toFixed(2) +
  ":  exact " + exact.toFixed(4) + ",  1+nx = " + approx.toFixed(4) +
  ",  error " + err.toFixed(2) + "%";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var cx = W * 0.30, cy = H * 0.42, Rp = Math.min(W, H) * 0.16;

// Earth
ctx.strokeStyle = C.ink; ctx.lineWidth = 1.8;
ctx.beginPath(); ctx.arc(cx, cy, Rp, 0, 6.2832); ctx.stroke();
ctx.fillStyle = C.ink; ctx.fillText("Earth", cx - 16, cy + 4);
ctx.fillStyle = C.faint; ctx.fillText("radius R", cx - 24, cy + 18);

// Moon direction marker on the right
ctx.strokeStyle = C.faint; ctx.lineWidth = 1; ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(cx + Rp, cy); ctx.lineTo(W - 12, cy); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.fillText("to Moon, distance d", W - 132, cy - 8);

function arrow(x, y, len, color, wid) {
  ctx.strokeStyle = color; ctx.fillStyle = color; ctx.lineWidth = wid;
  ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + len, y); ctx.stroke();
  var s = len > 0 ? 1 : -1, hx = x + len;
  ctx.beginPath();
  ctx.moveTo(hx, y); ctx.lineTo(hx - 7 * s, y - 4); ctx.lineTo(hx - 7 * s, y + 4);
  ctx.closePath(); ctx.fill();
}

// three nearly equal pulls
var base = W * 0.20;
var ys = [cy - Rp * 0.0 - 0, cy, cy];
var near = cx + Rp, far = cx - Rp;
var yNear = cy - 46, yCen = cy - 4, yFar = cy + 38;

ctx.fillStyle = C.ink;
ctx.fillText("Moon's pull on three points, drawn to scale:", 12, 18);

arrow(near + 6, yNear, base * 1.02, C.figure, 2);
ctx.fillStyle = C.figure; ctx.fillText("near side:  GM/(d−R)²", near + 10, yNear - 8);

arrow(cx + 6, yCen, base, C.figure, 2);
ctx.fillStyle = C.figure; ctx.fillText("centre:  GM/d²", cx + 10, yCen - 8);

arrow(far + 6, yFar, base * 0.98, C.figure, 2);
ctx.fillStyle = C.figure; ctx.fillText("far side:  GM/(d+R)²", far + 10, yFar - 8);

// residual after subtracting the centre value
var ry = H - 30;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(12, ry - 26); ctx.lineTo(W - 12, ry - 26); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("subtract the centre arrow from each, then magnify ×" + p.mag.toFixed(0) + ":", 12, ry - 11);

var resid = base * 0.02 * p.mag / 30;
arrow(cx + Rp + 6, ry + 6, resid, C.accent, 2.4);
arrow(cx - Rp - 6, ry + 6, -resid, C.accent, 2.4);
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(cx, ry + 6, Rp * 0.35, 0, 6.2832); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("2GMR/d³ outward, both ends — a stretch", cx + Rp + 14, ry + 22);

out.note = "Each long arrow is about 3.3e-5 m/s²; the difference between them is only 1.1e-6 m/s², about 3% as long. Shown magnified ×" + p.mag.toFixed(0) + ".";
